package proderrors

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

// TestGolden pins the port to TypeScript: testdata/golden.json is generated by test/fixtures/prodErrorsGolden.ts from
// src/prodErrors/scan.ts, and test/prod-errors-golden.test.ts fails when TypeScript changes without it.
func TestGolden(t *testing.T) {
	raw, err := os.ReadFile("testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Name    string `json:"name"`
		Day     string `json:"day"`
		Sources []struct {
			Source string `json:"source"`
			Rows   []Row  `json:"rows"`
		} `json:"sources"`
		Groups []any `json:"groups"`
	}
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		var sources []Source
		for _, s := range c.Sources {
			sources = append(sources, Source{Name: s.Source, Rows: s.Rows})
		}
		groups, err := ToGroups(MergeSourceRows(sources...), c.Day)
		if err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
		b, _ := json.Marshal(groups)
		var got []any
		_ = json.Unmarshal(b, &got)
		if got == nil {
			got = []any{}
		}
		if !reflect.DeepEqual(got, c.Groups) {
			for i := range min(len(got), len(c.Groups)) {
				if !reflect.DeepEqual(got[i], c.Groups[i]) {
					g, _ := json.Marshal(got[i])
					w, _ := json.Marshal(c.Groups[i])
					t.Fatalf("%s: group %d\n got %s\nwant %s", c.Name, i, g, w)
				}
			}
			t.Fatalf("%s: %d groups, want %d", c.Name, len(got), len(c.Groups))
		}
	}
}

func TestNumberConversionsMatchJavaScript(t *testing.T) {
	for in, want := range map[string]float64{" 7 ": 7, "": 0, "0x10": 16, "1e1": 10, "+5": 5, ".5": 0.5, "5.": 5} {
		if got := jsNumber(in); got != want {
			t.Errorf("Number(%q) = %v, want %v", in, got, want)
		}
	}
	for _, in := range []string{"1_000", "inf", "NaN", "0x1p-2", "12px"} {
		if got := jsNumber(in); got == got {
			t.Errorf("Number(%q) = %v, want NaN", in, got)
		}
	}
	for f, want := range map[float64]string{1e21: "1e+21", 1e20: "100000000000000000000", 1e-7: "1e-7",
		0.000001: "0.000001", 12.5: "12.5", 1290: "1290", 0.30000000000000004: "0.30000000000000004"} {
		if got := numberToString(f); got != want {
			t.Errorf("String(%v) = %q, want %q", f, got, want)
		}
	}
	if got := slice16("a🙂b", 2); got != "a�" {
		t.Errorf("slice16 = %q", got)
	}
}
